    annotations: [
        {
          id: 'a5.27.1',
          kind: "concept",
          refs: ['g5.27.2', 'g5.27.8'],
          lemma: "Υἱὸς ἀνθρώπου",
          title: "Domen given åt Människosonen",
          body: "Skälet till att Fadern anförtror domen åt honom är att **han är Människoson** — själva titeln i Daniel 7:13–14, där ”en som liknade en människoson” kommer till den Gamle och får evigt välde och domen över alla folk. Den som ska döma mänskligheten är själv människa — delar vårt kött, frestad, trött vid en brunn — och det är barmhärtighet: vi döms av en som inifrån vet vad det är att vara vi.",
        },
    ],
